import {createMotors,limitsFor,inRange,clamp,canSend,send,tickMotor,statusOf} from './state.js';
import {setupCharts,renderCharts,resetZoom} from './charts.js';
const $=id=>document.getElementById(id);
const motors=createMotors();let selected=motors[0],stopped=false,viewer=null,model=null,joints=[],mode='both';
let showGroups={ak:true,servo:true};
const jointLabels={shoulder_pitch_to_shoulder_roll:'어깨 1',shoulder_roll_to_shoulder_yaw:'어깨 2',shoulder_yaw_to_upper_arm:'위팔',upper_arm_to_under_arm:'팔꿈치',under_arm_to_wrist_pitch:'손목 1',wrist_pitch_to_wrist_yaw:'손목 2',wrist_yaw_to_hand_base:'손목 3',hand_base_to_rotation_base:'그리퍼 회전',hand_base_to_finger_1_1:'손가락 1 첫째',finger_1_1_to_finger_1_2:'손가락 1 둘째',hand_base_to_finger_2_1:'손가락 2 첫째',finger_1_2_to_finger_2_2:'손가락 2 둘째',rotation_base_to_finger_3_1:'손가락 3 첫째',finger_3_1_to_finger_3_2:'손가락 3 둘째'};
function toast(message,type='success'){const el=document.createElement('div');el.className=`toast ${type}`;const icon=document.createElement('span');icon.textContent=type==='error'?'✕':type==='warning'?'⚠':'✓';const text=document.createElement('span');text.textContent=message;el.append(icon,text);$('toasts').append(el);setTimeout(()=>el.remove(),5500);}
function fmt(n){return n===null?'—':`${n.toFixed(1)}°`;}
function errorState(m){return m.error||m.scenario==='error';}
function renderList(){const host=$('motor-list');const scroll=host.scrollTop;host.replaceChildren();const query=$('search').value.trim().toLowerCase();let count=0;for(const type of ['ak','servo']){const items=motors.filter(m=>m.type===type&&(`${m.name} ${m.id}`).toLowerCase().includes(query));if(!items.length)continue;count+=items.length;const group=document.createElement('details');group.className='motor-group';group.open=query?true:showGroups[type];const summary=document.createElement('summary');summary.textContent=type==='ak'?'AK45 모터':'STM32 서보';const groupCount=document.createElement('span');groupCount.textContent=String(items.length);summary.append(groupCount);group.append(summary);group.addEventListener('toggle',()=>{if(!$('search').value)showGroups[type]=group.open;});const list=document.createElement('div');list.className='group-items';for(const m of items){const b=document.createElement('button');b.className=`motor-item ${m===selected?'active':''} ${m.scenario==='offline'?'offline':''} ${errorState(m)?'error':''}`;b.setAttribute('aria-pressed',String(m===selected));b.setAttribute('aria-label',`${m.name}, ${m.scenario==='offline'?'연결 끊김':errorState(m)?'오류':'연결됨'}, ${m.type==='ak'?'현재 '+fmt(m.current):'실제 각도 피드백 없음'}`);b.innerHTML=`<i class="dot" style="background:${m.scenario==='offline'?'#64748b':errorState(m)?'#fb7185':'#4ade80'}"></i><span class="motor-name">${m.name}<small>ID ${m.id} · ${m.scenario==='offline'?'연결 끊김':m.joint?'관절 연결됨':'관절 미연결'}</small></span><span class="motor-angle">${m.error|| (m.scenario==='error'?'모터 오류':m.type==='ak'?fmt(m.current):'피드백 없음')}</span>`;b.onclick=()=>select(m);list.append(b);}group.append(list);host.append(group);}if(!count){const p=document.createElement('p');p.className='empty-list';p.textContent='검색 결과가 없습니다.';host.append(p);}host.scrollTop=scroll;}
function updateListValues(){for(const button of $('motor-list').querySelectorAll('.motor-item')){const name=button.querySelector('.motor-name').firstChild.textContent;const m=motors.find(m=>m.name===name);if(m)button.querySelector('.motor-angle').textContent=m.error||(m.scenario==='error'?'모터 오류':m.type==='ak'?fmt(m.current):'피드백 없음');}}
function syncInput(){const m=selected;$('target').min=m.min;$('target').max=m.max;$('slider').min=m.min;$('slider').max=m.max;$('target').value=m.draft.toFixed(1);$('slider').value=m.draft;$('range-hint').replaceChildren();for(const value of [m.min,(m.min+m.max)/2,m.max]){const span=document.createElement('span');span.textContent=fmt(value);$('range-hint').append(span);}$('input-error').textContent='';$('target').removeAttribute('aria-invalid');updateSlider();}
function updateSlider(){const m=selected,pct=(m.draft-m.min)/(m.max-m.min)*100;$('slider').style.background=`linear-gradient(to right,#8183ff ${pct}%,#303a51 ${pct}%)`;}
function select(m){selected=m;syncInput();render();}
function renderMapping(){const select=$('joint-map');select.replaceChildren(new Option('연결 안 됨 · 관절을 직접 지정하세요',''));for(const joint of joints){const owner=motors.find(m=>m!==selected&&m.joint===joint.name);const option=new Option(`${jointLabels[joint.name]??joint.child}${owner?' · '+owner.name+' 사용 중':''}`,joint.name);option.disabled=!!owner;select.append(option);}select.value=selected.joint;select.disabled=stopped||!model;$('mapping-help').textContent=selected.joint?`URDF: ${selected.joint} · 사용자가 지정한 대응입니다.`:'모델을 움직이려면 이 모터에 대응하는 관절을 먼저 선택하세요. 실제 대응표가 없어 자동 연결하지 않았습니다.';$('mapping-help').style.overflowWrap='anywhere';const mapped=motors.filter(m=>m.joint).length;$('mapping-count').textContent=`관절 연결 ${mapped} / 14`;$('model-notice').textContent=`${mapped?`관절 ${mapped}개 연결됨 · 사용자 지정 대응입니다.`:'관절 대응 미설정 · 오른쪽에서 모터에 대응하는 관절을 지정하세요.'} 서보와 미연결 관절의 회색 형상은 기준 자세이며 실제 피드백이 아닙니다.`;}
function render(){const m=selected;renderList();renderMapping();$('selected-name').textContent=m.name;$('motor-type').textContent=m.type==='ak'?'AK45-36 · 모터 ID '+m.id:'STM32 서보 · 모터 ID '+m.id;const disconnected=m.scenario==='offline',error=errorState(m);$('selected-status').textContent=disconnected?'● 연결 끊김':error?'● 오류':'● 연결됨';$('selected-status').className='pill '+(disconnected?'':error?'red':'green');$('online-count').textContent=`${motors.filter(m=>m.scenario!=='offline').length} / 14 모의 연결`;$('scenario').value=m.scenario;const ak=m.type==='ak';$('current-label').innerHTML=ak?'현재 각도 <small>모의 피드백</small>':'실제 각도 <small>피드백 미제공</small>';$('current-help').textContent=ak?(disconnected?'연결 끊김 · 마지막 수신 각도':'모의 데이터 · 실제 하드웨어 미연결'):'목표값과 실제 도달 위치는 다를 수 있습니다.';$('limit-source').textContent=m.joint?`URDF 관절 범위 · ${fmt(m.min)} ~ ${fmt(m.max)} (하드웨어 허용 범위 미확인)`:'관절 미연결 · 임시 데모 범위 −15.0° ~ +15.0°';$('preview-hint').textContent=m.joint?'입력한 목표 자세를 파란색 모델로 미리 확인하세요.':'아직 3D 관절이 연결되지 않았습니다. 위에서 관절을 선택해야 각도 조절과 이동이 가능합니다.';for(const id of ['target','slider','minus','plus','send','reset-target'])$(id).disabled=!canSend(m,stopped);$('reset-pose').disabled=stopped;$('batch-open').disabled=stopped;$('batch-preview').disabled=stopped;$('batch-send').disabled=stopped;$('scenario').disabled=stopped;$('connect-joint').disabled=stopped||!model;$('connect-joint').hidden=!!m.joint;$('send').innerHTML=m.joint?'설정한 각도로 이동 <span>↗</span>':'먼저 3D 관절을 연결하세요';$('emergency').hidden=!stopped;$('footer-state').textContent=stopped?'긴급 정지 중':'모의 제어 준비됨';$('difference-label').textContent=ak?'전송 목표까지 남은 각도':'위치 피드백';$('telemetry-name').textContent=m.name;$('telemetry-source').textContent=ak?'모의 피드백 · 최근 30초':'목표값 / PWM 설정 정보';$('ak-telemetry').hidden=!ak;$('servo-telemetry').hidden=ak;$('reset-charts').hidden=!ak;$('servo-id').textContent=String(m.id);$('servo-target').textContent=fmt(m.draft);$('servo-state').textContent=canSend(m,stopped)?'모의 전송 가능':statusOf(m,stopped);updateReadings();updatePreview();}
function updateReadings(){const m=selected;const ak=m.type==='ak';$('current-position').innerHTML=ak?`${m.current.toFixed(1)}<span>°</span>`:'<span>확인할 수 없음</span>';$('last-target').textContent=fmt(m.sent);$('motion').textContent=statusOf(m,stopped);$('motion').style.color=stopped||errorState(m)?'#fda4af':m.status==='reached'?'#6ee7b7':m.status==='moving'?'#a5b4fc':'#cbd5e1';$('difference').textContent=ak&&m.sent!==null&&m.scenario!=='offline'?fmt(Math.abs(m.sent-m.current)):ak?'—':'제공 안 됨';if(!ak)return;const values=[['현재 각도',m.current.toFixed(1),'°'],['전송 목표',m.sent===null?'—':m.sent.toFixed(1),'°'],['회전 속도',m.speed.toFixed(0),'ERPM'],['전류',m.amps.toFixed(2),'A'],['온도',m.temp.toFixed(1),'°C'],['오류 상태',m.error|| (m.scenario==='error'?'모의 오류 E01':m.scenario==='offline'?'연결 끊김':'정상'),'']];$('telemetry-values').replaceChildren();for(const [label,value,unit] of values){const div=document.createElement('div');div.className='telemetry-value';const span=document.createElement('span');span.textContent=label;const strong=document.createElement('strong');strong.textContent=m.scenario==='offline'&&label!=='오류 상태'?'—':value;const small=document.createElement('small');small.textContent=value==='—'?'':unit;strong.append(small);div.append(span,strong);$('telemetry-values').append(div);}renderCharts(m);}
function updatePreview(){viewer?.update(motors,selected.name);const m=selected;$('pose-readout').textContent=m.joint?`${m.name} → ${jointLabels[m.joint]??m.joint} · 현재 ${m.type==='ak'?fmt(m.current):'피드백 없음'} / 목표 미리보기 ${fmt(m.draft)} / 전송 목표 ${fmt(m.sent)}${mode==='actual'?' · 현재 자세만 보는 중 (미리보기 숨김)':''}`:`${m.name}: 3D 관절 미연결 — 관절을 선택해야 각도가 모델에 적용됩니다.`;$('pose-readout').classList.toggle('unmapped',!m.joint);const pending=motors.some(m=>m.joint&&Math.abs(m.draft-(m.sent??m.current??0))>.05);$('preview-state').hidden=!pending||mode==='actual';$('servo-target').textContent=fmt(selected.draft);}
function validate(){const m=selected,valid=inRange(m,$('target').value);$('target').setAttribute('aria-invalid',String(!valid));$('input-error').textContent=valid?'':`${fmt(m.min)} ~ ${fmt(m.max)} 사이의 숫자를 입력하세요.`;return valid;}
function saveMappings(){try{localStorage.setItem('jax-joint-mappings-v1',JSON.stringify(Object.fromEntries(motors.map(m=>[m.name,m.joint]))));}catch{toast('이 브라우저에서 관절 연결을 저장할 수 없습니다.','warning');}}
$('search').oninput=renderList;
$('connect-joint').onclick=()=>{$('joint-map').scrollIntoView({behavior:'smooth',block:'center'});$('joint-map').focus();};
$('joint-map').onchange=()=>{if(stopped)return;const m=selected,name=$('joint-map').value,joint=joints.find(j=>j.name===name);if(name&&(!joint||motors.some(other=>other!==m&&other.joint===name))){toast('이미 다른 모터에 연결된 관절입니다.','warning');renderMapping();return;}m.joint=name;Object.assign(m,limitsFor(joint));m.draft=clamp(m,m.draft);/* A new mapping establishes a new mock model context; no hardware feedback is implied. */if(m.type==='ak')m.current=clamp(m,m.current);m.sent=null;m.status='idle';m.history=[];saveMappings();syncInput();render();toast(name?`${m.name}에 ${jointLabels[name]??name} 관절을 연결했습니다.`:'관절 연결을 해제했습니다.');};
$('target').oninput=()=>{if(validate()){selected.draft=Number($('target').value);$('slider').value=selected.draft;updateSlider();updatePreview();}};
$('target').onchange=()=>{if(validate()){selected.draft=Number($('target').value);syncInput();}};
$('slider').oninput=()=>{selected.draft=Number($('slider').value);syncInput();updatePreview();};
function step(delta){if(!canSend(selected,stopped))return;selected.draft=clamp(selected,(Number($('target').value)||0)+delta);syncInput();updatePreview();}
$('minus').onclick=()=>step(-.1);$('plus').onclick=()=>step(.1);
function resetTarget(m){m.draft=clamp(m,m.type==='ak'?m.current:m.sent??0);}
$('reset-target').onclick=()=>{if(!canSend(selected,stopped))return;resetTarget(selected);syncInput();updatePreview();};
$('reset-pose').onclick=()=>{if(stopped)return;motors.forEach(resetTarget);syncInput();updatePreview();toast('목표 자세를 초기화했습니다. 모터에는 전송하지 않았습니다.');};
function sendSelected(){if(!validate()){toast('목표 각도가 허용 범위를 벗어났습니다.','warning');return;}selected.draft=Number($('target').value);const result=send(selected,stopped);toast(result.message,result.ok?'success':'error');render();}
$('command-form').onsubmit=event=>{event.preventDefault();sendSelected();};
$('stop').onclick=()=>{stopped=true;motors.forEach(m=>{m.status='idle';m.speed=0;});render();toast('긴급 정지 요청 · 모든 모의 이동을 멈추고 제어를 잠갔습니다.','warning');};
$('batch-stop').onclick=()=>{$('batch-dialog').close();$('stop').onclick();};
$('reset-stop').onclick=()=>{stopped=false;render();toast('제어 잠금을 해제했습니다. 이전 이동은 자동으로 재개되지 않습니다.');};
$('scenario').onchange=()=>{const m=selected;m.scenario=$('scenario').value;m.status='idle';m.speed=0;m.error=m.scenario==='error'?'모의 모터 오류 E01':'';render();toast(m.scenario==='normal'?`${m.name} 모의 연결을 복구했습니다.`:m.scenario==='offline'?`${m.name} 연결이 끊겼습니다.`:m.scenario==='error'?`${m.name} 오류가 발생했습니다. 모터 목록에서 상태를 확인하세요.`:'다음 명령 전송이 실패하도록 설정했습니다.',m.scenario==='normal'?'success':m.scenario==='error'?'error':'warning');};
$('pose-modes').onclick=event=>{const button=event.target.closest('button[data-mode]');if(!button)return;mode=button.dataset.mode;for(const item of $('pose-modes').querySelectorAll('button')){item.classList.toggle('active',item===button);item.setAttribute('aria-pressed',String(item===button));}viewer?.setMode(mode);$('pose-label').textContent={actual:'현재 자세 · AK45 모의 피드백',target:'목표 자세 · 미리보기',both:'현재 + 목표 자세'}[mode];updatePreview();};
async function fullscreen(element){try{if(document.fullscreenElement)await document.exitFullscreen();else await element.requestFullscreen();}catch{toast('이 브라우저에서는 전체 화면을 사용할 수 없습니다.','warning');}}
$('fullscreen').onclick=()=>fullscreen($('twin-panel'));$('reset-view').onclick=()=>viewer?.reset();
setupCharts(fullscreen);$('reset-charts').onclick=()=>{selected.history=[];resetZoom();renderCharts(selected);toast('선택한 모터의 그래프 기록과 확대를 초기화했습니다.');};
$('batch-open').onclick=()=>{if(stopped)return;const host=$('batch-fields');host.replaceChildren();for(const m of motors){const label=document.createElement('label');label.className='batch-field';const text=document.createElement('span');text.textContent=m.name;const small=document.createElement('small');small.textContent=`${fmt(m.min)} ~ ${fmt(m.max)}${!m.joint?' · 관절 연결 필요':canSend(m,stopped)?'':' · 전송 불가'}`;text.append(small);const input=document.createElement('input');input.type='number';input.step='.1';input.min=m.min;input.max=m.max;input.value=m.draft.toFixed(1);input.disabled=!canSend(m,stopped);input.dataset.motor=m.name;input.setAttribute('aria-label',m.name+' 목표 각도');label.append(text,input);host.append(label);}$('batch-error').textContent='';$('batch-dialog').showModal();};
function applyBatch(){if(stopped)return null;const inputs=[...$('batch-fields').querySelectorAll('input:not(:disabled)')];if(!inputs.length){$('batch-error').textContent='전송 가능한 모터가 없습니다.';return null;}for(const input of inputs){const m=motors.find(m=>m.name===input.dataset.motor);if(!inRange(m,input.value)){$('batch-error').textContent=`${m.name}: ${fmt(m.min)} ~ ${fmt(m.max)} 사이의 숫자를 입력하세요.`;input.focus();return null;}}const affected=inputs.map(input=>{const m=motors.find(m=>m.name===input.dataset.motor);m.draft=Number(input.value);return m;});syncInput();updatePreview();$('batch-error').textContent='';return affected;}
$('batch-preview').onclick=()=>{if(applyBatch()){$('batch-dialog').close();toast('여러 모터의 목표 자세를 적용했습니다. 아직 전송하지 않았습니다.');}};
$('batch-send').onclick=()=>{const affected=applyBatch();if(!affected)return;const results=affected.map(m=>({motor:m,result:send(m,stopped)}));$('batch-dialog').close();const failed=results.filter(r=>!r.result.ok);render();toast(failed.length?`${results.length-failed.length}개 전송 완료 · ${failed.map(r=>r.motor.name).join(', ')} 전송 실패`:`${results.length}개 모터에 모의 명령을 전송했습니다.`,failed.length?'error':'success');};
syncInput();render();
let last=performance.now(),sample=0;setInterval(()=>{const now=performance.now(),dt=Math.min((now-last)/1000,.5);last=now;const t=now/1000;motors.forEach(m=>{if(tickMotor(m,dt,stopped))toast(`${m.name}이 목표 ${fmt(m.sent)}에 도착했습니다. (모의 피드백)`);});if(now-sample>240){sample=now;motors.filter(m=>m.type==='ak'&&m.scenario!=='offline').forEach(m=>{m.history.push({t,position:m.current,target:m.sent,speed:m.speed,amps:m.amps,temp:m.temp});m.history=m.history.filter(p=>p.t>t-65);});updateListValues();updateReadings();updatePreview();}},100);
async function loadModel(){try{const response=await fetch('./models/jax/model.json');if(!response.ok)throw Error('URDF 모델 데이터를 불러오지 못했습니다.');model=await response.json();joints=model.joints.filter(j=>j.type!=='fixed');try{const mappings=JSON.parse(localStorage.getItem('jax-joint-mappings-v1')??'{}');const assigned=new Set();motors.forEach(m=>{const joint=joints.find(j=>j.name===mappings[m.name]);if(joint&&!assigned.has(joint.name)){m.joint=joint.name;assigned.add(joint.name);Object.assign(m,limitsFor(joint));m.draft=clamp(m,m.draft);if(m.type==='ak')m.current=clamp(m,m.current);}});}catch{/* A malformed or unavailable local preference must not block model loading. */}syncInput();render();const {createViewer}=await import('./viewer.js');viewer=await createViewer($('viewer'),model,(name,joint)=>{if(name){const m=motors.find(m=>m.name===name);$('search').value='';showGroups[m.type]=true;select(m);$('motor-list').querySelector('[aria-pressed="true"]')?.scrollIntoView({block:'nearest'});}else toast(`${jointLabels[joint]??joint}: 대응 모터가 없어 선택할 수 없습니다. 오른쪽에서 직접 연결하세요.`,'warning');});viewer.setMode(mode);viewer.update(motors,selected.name);$('model-loading').hidden=true;}catch(error){console.error(error);$('model-loading').textContent='3D 모델을 표시하지 못했습니다. WebGL 지원 여부를 확인하고 페이지를 새로고침하세요. 모터 제어 UI는 계속 사용할 수 있습니다.';toast('3D 뷰어 초기화에 실패했습니다.','error');}}
loadModel();
